 */
scwin.listSync = async function() {
    if (txb_date1.getValue() === "") {
        await $c.win.alert("시작일을 지정하여주십시요");
        return;
    }
    if (txb_date2.getValue() === "") {
        await $c.win.alert("종료일을 지정하여주십시요");
        return;
    }
    const cdCase1 = "&LIST_BZ_TP_CD=" + MxDataSet_code1.getCellData(MxCombo1.getSelectedIndex() + 1, "CD_VAL");
    const cdCase2 = "&LIST_PROCS_STAT_CD=" + MxDataSet_code2.getCellData(MxCombo2.getSelectedIndex() + 1, "CD_VAL");
    const cdCase3 = "&LD_MKT_TP_CD=" + MxDataSet_code3.getCellData(MxCombo3.getSelectedIndex() + 1, "CD_VAL");
    const cdCase4 = "&ISUR_CD=" + ISUR_CD.getValue();
    const cdCase5 = "&DDTM_FROM=" + txb_date1.getValue() + "&DDTM_TO=" + txb_date2.getValue() + "&DDTM_CD=" + MxRadio.getValue();
    const sbmOptions = {
        id : "sbm_MxDataSet_stat",
        action : "/listprocsstat.do",
        ref : "",
        target : "MxDataSet_stat=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

